import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './DashboardLayout.css';

const DashboardLayout = () => {
  const { user, logout, isAdmin, isReceptionist } = useAuth();
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const navLinks = [
    { to: '/dashboard', label: 'Accueil', icon: '⊞' },
    ...(isAdmin || isReceptionist
      ? [{ to: '/reception/dashboard', label: 'Réservations', icon: '◫' }]
      : [{ to: '/client/dashboard', label: 'Mes séjours', icon: '◫' }]
    ),
    ...(isAdmin
      ? [{ to: '/admin/dashboard', label: 'Administration', icon: '⊙' }]
      : []
    ),
  ];

  const roleLabel = {
    admin: 'Administrateur',
    receptionist: 'Réceptionniste',
    client: 'Client',
  }[user?.role] || '';

  return (
    <div className="dash-layout">
      {/* Sidebar */}
      <aside className={`dash-sidebar ${menuOpen ? 'is-open' : ''}`}>
        <div className="dash-sidebar__logo">
          <span className="dash-sidebar__logo-icon">✦</span>
          <span className="dash-sidebar__logo-text">Grand Hôtel</span>
        </div>

        <nav className="dash-nav">
          {navLinks.map(({ to, label, icon }) => (
            <NavLink
              key={to}
              to={to}
              className={({ isActive }) =>
                `dash-nav__link ${isActive ? 'is-active' : ''}`
              }
              onClick={() => setMenuOpen(false)}
            >
              <span className="dash-nav__icon">{icon}</span>
              {label}
            </NavLink>
          ))}
        </nav>

        <div className="dash-sidebar__user">
          <div className="dash-sidebar__avatar">
            {user?.name?.charAt(0).toUpperCase()}
          </div>
          <div className="dash-sidebar__info">
            <p className="dash-sidebar__name">{user?.name}</p>
            <p className="dash-sidebar__role">{roleLabel}</p>
          </div>
          <button className="dash-sidebar__logout" onClick={handleLogout} title="Déconnexion">
            ⏻
          </button>
        </div>
      </aside>

      {/* Overlay mobile */}
      {menuOpen && (
        <div className="dash-overlay" onClick={() => setMenuOpen(false)} />
      )}

      {/* Contenu principal */}
      <main className="dash-main">
        <header className="dash-topbar">
          <button
            className="dash-topbar__burger"
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label="Menu"
          >
            ☰
          </button>
          <h1 className="dash-topbar__title">
            Bienvenue, {user?.name?.split(' ')[0]}
          </h1>
        </header>

        <div className="dash-content">
          <Outlet />
        </div>
      </main>
    </div>
  );
};

export default DashboardLayout;
